from lxml import etree
from base.spider import Spider

class Spider(Spider):
    def getName(self):
        return "92电影网"

    def init(self, extend=""):
        self.host = "https://www.92dyw.net"
        self.headers = {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
            "Referer": self.host + "/"
        }
        self.categories = [
            {"type_id": "1", "type_name": "电影"},
            {"type_id": "2", "type_name": "电视剧"},
            {"type_id": "3", "type_name": "综艺"},
            {"type_id": "4", "type_name": "动漫"}
        ]

    def _get(self, url):
        try:
            r = requests.get(url, headers=self.headers, timeout=15)
            r.encoding = r.apparent_encoding or "utf-8"
            return r.text
        except Exception as e:
            print(f"[ERROR] 请求失败: {url}, 错误: {str(e)}")
            return None

    def _post(self, url, data):
        try:
            r = requests.post(url, data=data, headers=self.headers, timeout=15)
            r.encoding = r.apparent_encoding or "utf-8"
            return r.text
        except Exception as e:
            print(f"[ERROR] POST失败: {url}, 错误: {str(e)}")
            return None

    def _fix(self, u):
        if not u:
            return ""
        if u.startswith("//"):
            return "https:" + u
        if u.startswith("/"):
            return self.host + u
        return u

    def _parse_list(self, html):
        """解析视频列表，兼容首页和分类页"""
        if not html:
            return []
        tree = etree.HTML(html)
        results = []
        seen = set()

        items = tree.xpath('//li[contains(@class,"col-md-6")]//div[contains(@class,"stui-vodlist__box")]')
        if not items:
            items = tree.xpath('//li[contains(@class,"col-lg-6")]//div[contains(@class,"stui-vodlist__box")]')
        if not items:
            items = tree.xpath('//div[contains(@class,"stui-vodlist__box")]')

        for item in items:
            try:
                a = item.xpath('.//a[contains(@class,"stui-vodlist__thumb")]')[0]
                href = a.get("href", "")
                m = re.search(r"/(\d+)\.html", href)
                if not m or m.group(1) in seen:
                    continue
                vid = m.group(1)
                seen.add(vid)

                img = a.xpath('.//img')
                pic = ""
                if img:
                    pic = img[0].get("data-original") or img[0].get("data-src") or img[0].get("src", "")
                pic = self._fix(pic)

                title = a.get("title", "") or "".join(item.xpath('.//h4[@class="title"]/a/text()')).strip()
                if not title:
                    title = "".join(a.xpath('.//text()')).strip()

                remark = ""
                pic_text = a.xpath('.//span[contains(@class,"pic-text")]/text()')
                if pic_text:
                    remark = pic_text[0].strip()

                results.append({
                    "vod_id": vid,
                    "vod_name": title,
                    "vod_pic": pic,
                    "vod_remarks": remark
                })
            except Exception as e:
                continue
        return results

    def homeContent(self, filter):
        html = self._get(self.host + "/")
        return {
            "class": self.categories,
            "list": self._parse_list(html) if html else [],
            "filters": {}
        }

    def categoryContent(self, tid, pg, filter, extend):
        url = f"{self.host}/type/{tid}.html"
        if pg and int(pg) > 1:
            url += f"?page={pg}"
        html = self._get(url)
        data_list = self._parse_list(html) if html else []

        pagecount = 99
        if html:
            tree = etree.HTML(html)
            last_page = tree.xpath('//ul[contains(@class,"stui-page")]//li/a[contains(text(),"尾页")]/@href')
            if last_page:
                m = re.search(r"/(\d+)\.html", last_page[0])
                if m:
                    pagecount = int(m.group(1))
            else:
                num_span = tree.xpath('//ul[contains(@class,"stui-page")]//span[contains(@class,"num")]/text()')
                if num_span:
                    m = re.search(r"(\d+)/(\d+)", num_span[0])
                    if m:
                        pagecount = int(m.group(2))

        return {
            "page": int(pg) if pg else 1,
            "pagecount": pagecount,
            "limit": 36,
            "total": pagecount * 36,
            "list": data_list
        }

    def detailContent(self, ids):
        result = {"list": []}
        for vid in ids:
            try:
                html = self._get(f"{self.host}/movie/{vid}.html")
                if not html:
                    continue
                tree = etree.HTML(html)

                name = "".join(tree.xpath('//h1[@class="title"]/text()')).strip()
                if not name:
                    name = "".join(tree.xpath('//h1/text()')).strip()

                pic = ""
                img = tree.xpath('//div[contains(@class,"stui-content__thumb")]//img/@data-original')
                if not img:
                    img = tree.xpath('//div[contains(@class,"stui-content__thumb")]//img/@src')
                if img:
                    pic = self._fix(img[0])

                sources = []
                episodes = []

                tabs = tree.xpath('//ul[contains(@class,"nav-tabs")]/li/a')
                tab_names = []
                for tab in tabs:
                    name_tab = "".join(tab.xpath('.//text()')).strip()
                    if name_tab:
                        tab_names.append(name_tab)
                if not tab_names:
                    tab_names = ["线路1"]

                contents = tree.xpath('//div[contains(@class,"tab-content")]/div[contains(@class,"tab-pane")]')
                for idx, content in enumerate(contents):
                    src_name = tab_names[idx] if idx < len(tab_names) else f"线路{idx+1}"
                    eps = content.xpath('.//ul[contains(@class,"stui-content__playlist")]/li/a')
                    if not eps:
                        eps = content.xpath('.//ul/li/a')
                    ep_list = []
                    for a in eps:
                        ep_name = "".join(a.xpath('.//text()')).strip()
                        ep_href = a.get("href", "")
                        if ep_href:
                            ep_list.append(f"{ep_name}${self._fix(ep_href)}")
                    if ep_list:
                        sources.append(src_name)
                        episodes.append("#".join(ep_list))

                if not sources:
                    all_playlist = tree.xpath('//ul[contains(@class,"stui-content__playlist")]')
                    for idx, ul in enumerate(all_playlist):
                        eps = ul.xpath('.//li/a')
                        ep_list = []
                        for a in eps:
                            ep_name = "".join(a.xpath('.//text()')).strip()
                            ep_href = a.get("href", "")
                            if ep_href:
                                ep_list.append(f"{ep_name}${self._fix(ep_href)}")
                        if ep_list:
                            sources.append(f"线路{idx+1}")
                            episodes.append("#".join(ep_list))

                result["list"].append({
                    "vod_id": vid,
                    "vod_name": name,
                    "vod_pic": pic,
                    "vod_play_from": "$$$".join(sources),
                    "vod_play_url": "$$$".join(episodes)
                })
            except Exception as e:
                print(f"[ERROR] 详情解析失败: {vid}, 错误: {str(e)}")
                continue
        return result

    def searchContent(self, key, quick, pg="1"):
        url = self.host + "/search.php"
        data = {"searchword": key}
        html = self._post(url, data)
        return {
            "list": self._parse_list(html) if html else [],
            "page": int(pg) if pg else 1
        }

    def playerContent(self, flag, id, vipFlags):
        url = self._fix(id)
        if any(x in url for x in [".m3u8", ".mp4"]):
            return {"parse": 0, "url": url, "header": json.dumps(self.headers)}

        html = self._get(url)
        if not html:
            return {"parse": 1, "url": url, "header": json.dumps(self.headers)}

        play_url = None

        m = re.search(r'var\s+player_aaaa\s*=\s*(\{.*?\});', html, re.S)
        if m:
            try:
                data = json.loads(m.group(1))
                play_url = data.get('url')
            except:
                pass

        if not play_url:
            m = re.search(r'var\s+player_data\s*=\s*(\{.*?\});', html, re.S)
            if m:
                try:
                    data = json.loads(m.group(1))
                    play_url = data.get('url')
                except:
                    pass

        if not play_url:
            m = re.search(r'<video[^>]*src=[\"\']([^\"\']+)[\"\']', html)
            if m:
                play_url = m.group(1)

        if not play_url:
            m = re.search(r'<iframe[^>]*src=[\"\']([^\"\']+)[\"\']', html)
            if m:
                play_url = m.group(1)
                if ".m3u8" not in play_url:
                    return self.playerContent(flag, play_url, vipFlags)

        if not play_url:
            patterns = [
                r'var\s+now\s*=\s*["\']([^"\']+\.m3u8[^"\']*)["\']',
                r'url:\s*["\']([^"\']+\.m3u8[^"\']*)["\']',
                r'(https?://[^\s"\']+\.m3u8[^\s"\']*)'
            ]
            for p in patterns:
                m = re.search(p, html)
                if m:
                    val = m.group(1)
                    if ".m3u8" not in val and "{" in val:
                        m2 = re.search(r'"(https?://[^"]+\.m3u8[^"]*)"', val)
                        if m2:
                            play_url = m2.group(1)
                            break
                    else:
                        play_url = val
                        break

        if play_url:
            play_url = self._fix(play_url)
            return {"parse": 0, "url": play_url, "header": json.dumps(self.headers)}

        return {"parse": 1, "url": url, "header": json.dumps(self.headers)}